<?php
require __DIR__.'/../config/app.php';require_role('admin');
$reportType=$_GET['type']??'events';if(!in_array($reportType,['events','volunteer','analytics'],true))$reportType='events';
$from=trim((string)($_GET['from']??''));$to=trim((string)($_GET['to']??''));$search=trim((string)($_GET['q']??''));
$validDate=static function(string $v):bool{if($v==='')return true;$d=DateTime::createFromFormat('Y-m-d',$v);return $d&&$d->format('Y-m-d')===$v;};if(!$validDate($from))$from='';if(!$validDate($to))$to='';
$where=[];$params=[];if($from!==''){$where[]='DATE(%s)>=?';$params[]=$from;}if($to!==''){$where[]='DATE(%s)<=?';$params[]=$to;}
$rangeSql=static function(string $column)use($from,$to):array{$parts=[];$args=[];if($from!==''){$parts[]="DATE($column)>=?";$args[]=$from;}if($to!==''){$parts[]="DATE($column)<=?";$args[]=$to;}return [$parts?(' WHERE '.implode(' AND ',$parts)):'',$args];};
$data=[];$stats=['events'=>0,'applications'=>0,'students'=>0,'hours'=>0];$pdo=db();
try{
 $stats['events']=(int)$pdo->query('SELECT COUNT(*) FROM events')->fetchColumn();$stats['applications']=(int)$pdo->query('SELECT COUNT(*) FROM event_applications')->fetchColumn();$stats['students']=(int)$pdo->query("SELECT COUNT(*) FROM users WHERE role='student'")->fetchColumn();$stats['hours']=(float)$pdo->query('SELECT COALESCE(SUM(hours),0) FROM volunteer_hours WHERE is_verified=1')->fetchColumn();
 if($reportType==='events'){[$w,$p]=$rangeSql('a.applied_at');$sql='SELECT e.category,COUNT(DISTINCT e.id) event_count,COUNT(a.id) applications FROM events e LEFT JOIN event_applications a ON a.event_id=e.id'.($w?' AND '.substr($w,7):'').' GROUP BY e.category ORDER BY event_count DESC';$q=$pdo->prepare($sql);$q->execute($p);$data=$q->fetchAll();}
 elseif($reportType==='volunteer'){[$w,$p]=$rangeSql('va.created_at');[$hw,$hp]=$rangeSql('vh.recorded_at');$p=array_merge($p,$hp);$studentFilter=$search!==''?' AND (u.name LIKE ? OR u.email LIKE ?)':'';if($search!==''){$p[]='%'.$search.'%';$p[]='%'.$search.'%';}$sql="SELECT u.name,u.email,COALESCE(a.applications,0) applications,COALESCE(h.verified_hours,0) verified_hours FROM users u LEFT JOIN (SELECT user_id,COUNT(*) applications FROM volunteer_applications va".($w?$w:'')." GROUP BY user_id) a ON a.user_id=u.id LEFT JOIN (SELECT user_id,SUM(hours) verified_hours FROM volunteer_hours vh WHERE vh.is_verified=1".($hw?' AND '.substr($hw,7):'')." GROUP BY user_id) h ON h.user_id=u.id WHERE u.role='student'".$studentFilter.' ORDER BY verified_hours DESC,u.name';$q=$pdo->prepare($sql);$q->execute($p);$data=$q->fetchAll();}
 else{[$w,$p]=$rangeSql('a.applied_at');$q=$pdo->prepare('SELECT DATE_FORMAT(a.applied_at,\'%b %Y\') period,COUNT(*) applications FROM event_applications a'.$w.' GROUP BY YEAR(a.applied_at),MONTH(a.applied_at),DATE_FORMAT(a.applied_at,\'%b %Y\') ORDER BY YEAR(a.applied_at),MONTH(a.applied_at)');$q->execute($p);$data=$q->fetchAll();}
}catch(Throwable $t){$data=[];}
if(($_GET['export']??'')==='csv'){$filename='eventhub-'.$reportType.'-'.date('Ymd').'.csv';header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="'.$filename.'"');$out=fopen('php://output','w');fputcsv($out,$reportType==='events'?['Category','Events','Applications']:($reportType==='volunteer'?['Student','Email','Applications','Verified hours']:['Month','Applications']));foreach($data as $row)fputcsv($out,array_values($row));fclose($out);exit;}
$titles=['events'=>'Event Reports','volunteer'=>'Volunteer Reports','analytics'=>'Analytics'];$pageTitle=$titles[$reportType];$bodyClass='dashboard-page admin-page';$activePage='reports';$adminSection='reports';require __DIR__.'/../includes/header.php';
?><div class="dash-layout admin-layout"><?php require __DIR__.'/../includes/sidebar.php';?><main class="content-page admin-content admin-events-page"><header class="admin-page-heading"><div><span class="admin-eyebrow">REPORTS & ANALYTICS</span><h1><?=$titles[$reportType]?></h1><p><?=$reportType==='events'?'Event participation by category and application volume.':($reportType==='volunteer'?'Verified volunteer hours and submitted applications by student.':'A summary of current EventHub activity.')?></p></div></header><?php require __DIR__.'/section-nav.php';?><div class="admin-summary-grid"><?php foreach([['Total events',$stats['events'],'calendar','teal'],['Event applications',$stats['applications'],'clipboard','violet'],['Students',$stats['students'],'people','mint'],['Verified hours',number_format($stats['hours'],1),'chart','orange']] as [$label,$value,$icon,$tone]):?><article class="admin-summary-card"><span class="admin-summary-icon <?=$tone?>"><?=eventhub_icon($icon)?></span><div><small><?=e($label)?></small><strong><?=e((string)$value)?></strong></div></article><?php endforeach;?></div><section class="admin-work-card"><form method="get" class="admin-report-filters"><input type="hidden" name="type" value="<?=e($reportType)?>"><label>From<input type="date" name="from" value="<?=e($from)?>"></label><label>To<input type="date" name="to" value="<?=e($to)?>"></label><?php if($reportType==='volunteer'):?><label>Student<input name="q" value="<?=e($search)?>" placeholder="Name or email"></label><?php endif;?><button class="btn primary" type="submit">Apply Filters</button><a class="btn outline" href="<?=url('admin/reports.php?'.http_build_query(['type'=>$reportType,'from'=>$from,'to'=>$to,'q'=>$search,'export'=>'csv']))?>">Export CSV</a></form></section><section class="admin-work-card"><div class="admin-card-heading"><span class="admin-heading-icon"><?=eventhub_icon('chart')?></span><div><h2><?=$reportType==='events'?'Applications by event category':($reportType==='volunteer'?'Volunteer participation':'Applications over time')?> <span class="admin-count"><?=count($data)?></span></h2><p>Figures are calculated from saved records and current filters.</p></div></div><?php if($data):?><div class="table-wrap admin-table-wrap"><table><thead><?php if($reportType==='events'):?><tr><th>Category</th><th>Events</th><th>Applications</th></tr><?php elseif($reportType==='volunteer'):?><tr><th>Student</th><th>Email</th><th>Applications</th><th>Verified hours</th></tr><?php else:?><tr><th>Month</th><th>Applications</th></tr><?php endif;?></thead><tbody><?php foreach($data as $r):?><tr><?php if($reportType==='events'):?><td><span class="pill <?=e($r['category'])?>"><?=e(ucfirst($r['category']))?></span></td><td><?=(int)$r['event_count']?></td><td><?=(int)$r['applications']?></td><?php elseif($reportType==='volunteer'):?><td><strong><?=e($r['name'])?></strong></td><td><?=e($r['email'])?></td><td><?=(int)$r['applications']?></td><td><?=number_format((float)$r['verified_hours'],1)?></td><?php else:?><td><?=e($r['period'])?></td><td><?=(int)$r['applications']?></td><?php endif;?></tr><?php endforeach;?></tbody></table></div><?php else:?><div class="empty">There is no report data for these filters.</div><?php endif;?></section></main></div><?php require __DIR__.'/../includes/footer.php';
